<template>
  <view class="mini-nav" role="navigation" aria-label="主要导航">
    <view v-for="item in items" :key="item.key" class="mini-nav-item" :class="['k-'+item.key,{'is-active': activeKey === item.key}]" role="link" :aria-label="item.label" hover-class="mini-nav-press" @tap="go(item)">
      <view v-if="item.key==='find'" class="mini-nav-ava">
        <image class="mini-nav-ava-img" :src="avatar" mode="aspectFill" />
        <view class="mini-nav-lens"><text>⌕</text></view>
      </view>
      <view v-else class="mini-nav-ic"><image class="mini-nav-icon" :src="activeKey===item.key ? item.icon.on : item.icon.off" mode="aspectFit" /></view>
      <text class="mini-nav-label">{{item.label}}</text>
      <view v-if="item.key==='daily' && dailyDot" class="mini-nav-dot" />
    </view>
  </view>
</template>

<script setup>
// 小程序底部导航：首页 / 每日 AI / 找用法（中间的小A）/ 学 AI / 我的。和网站底部导航（static/learn/ai-nav.js）一致。
// 「快捷提示词」放进了找用法，「跟着做」放进了学 AI；这些页面传来的旧 key 也会点亮对应的位置。
import { computed, ref, onMounted } from 'vue';
import mini from '../data/mini-ai.json';
import { ROLES, loadStore, issueByDate, ymd } from '../data/ai-core.js';
const props = defineProps({ active: { type: String, default: 'home' } });
const ALIAS = { library: 'find', learn: 'study', guides: 'study' };
const activeKey = computed(() => ALIAS[props.active] || props.active);
const avatar = ROLES.a.src;
// 图标是内嵌的小图片，不走网络、不占小程序包里的 static 目录
const items = [
  { key: 'home', label: '首页', url: '/pages/discover/index', icon: {on:'data:image/png;base64,',off:'data:image/png;base64,'} },
  { key: 'daily', label: '每日 AI', url: '/pages/learn/daily', icon: {on:'data:image/png;base64,',off:'data:image/png;base64,'} },
  { key: 'find', label: '找用法', url: '/pages/learn/find' },
  { key: 'study', label: '学 AI', url: '/pages/learn/learning', icon: {on:'data:image/png;base64,',off:'data:image/png;base64,'} },
  { key: 'saved', label: '我的', url: '/pages/learn/mine', icon: {on:'data:image/png;base64,',off:'data:image/png;base64,'} },
];
// 今天这期还没玩时，每日 AI 上亮一个小蓝点
const dailyDot = ref(false);
onMounted(() => {
  try { const is = issueByDate(mini.meiri.ISSUES, ymd(new Date())); dailyDot.value = !!(is && !loadStore(uni).daily[is.id]); } catch { dailyDot.value = false; }
});
function go(item) {
  const pages = getCurrentPages();
  const route = pages.length ? '/' + pages[pages.length - 1].route : '';
  if (route === item.url) return;
  // These are peer sections. Replacing the current tab keeps the page stack small.
  uni.redirectTo({url:item.url, fail:()=>uni.navigateTo({url:item.url})});
}
</script>

<style scoped>
.mini-nav{position:fixed;z-index:100;left:0;right:0;bottom:0;display:flex;align-items:flex-end;min-height:60px;padding:0 4px env(safe-area-inset-bottom);background:#fff;border-top:1px solid #e6e8ec;box-shadow:0 -6px 18px -12px rgba(22,26,35,.35)}
.mini-nav-item{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;min-height:58px;padding-bottom:6px;color:#7f8a9b}
.mini-nav-press{opacity:.7}
.mini-nav-ic{display:flex;align-items:center;justify-content:center;width:46px;height:30px;border-radius:12px;margin-bottom:2px}
.mini-nav-icon{width:23px;height:23px}
.mini-nav-label{font-size:10px;line-height:15px;white-space:nowrap;font-weight:600}
.mini-nav-item.is-active{color:#2b44e6}
.mini-nav-item.is-active .mini-nav-label{font-weight:800}
.mini-nav-item.is-active .mini-nav-ic{background:#eceffe;animation:navPop .55s ease}
/* 中间的小A */
.mini-nav-ava{position:relative;width:52px;height:52px;margin-top:-26px;margin-bottom:2px;border-radius:50%;padding:3px;box-sizing:border-box;background:#2b44e6;box-shadow:0 0 0 4px #fff,0 10px 20px -8px rgba(43,68,230,.85)}
.mini-nav-ava-img{display:block;width:46px;height:46px;border-radius:50%;background:#fff;animation:navBob 2.8s ease-in-out infinite}
.mini-nav-lens{position:absolute;right:-5px;bottom:-3px;width:20px;height:20px;border-radius:50%;background:#fff;color:#2b44e6;font-size:13px;line-height:20px;text-align:center;font-weight:900;box-shadow:0 2px 6px rgba(22,26,35,.2)}
.mini-nav-item.k-find{color:#2b44e6}
.mini-nav-item.k-find.is-active .mini-nav-label{text-decoration:underline}
.mini-nav-dot{position:absolute;top:6px;left:50%;margin-left:10px;width:8px;height:8px;border-radius:50%;background:#2b44e6;box-shadow:0 0 0 2px #fff}
@keyframes navPop{0%{transform:scale(.7)}60%{transform:scale(1.12)}100%{transform:scale(1)}}
@keyframes navBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}
</style>
